async function importRoster(){return AdvaconReviewedImport({api,people,reload,loadSheetJS,ar});}
function activeFleetAssignment(rows,key,id,now=Date.now()){
 return rows.find(x=>x[key]===id&&Date.parse(x.starts_on)<=now&&(!x.ends_on||Date.parse(x.ends_on)>now));
}
function cardHolderPeriods(data,cardId,now=Date.now()){
 const periods=[];
 for(const a of data.card_assignments.filter(x=>x.card_id===cardId)){
  const start=Date.parse(a.starts_on),end=a.ends_on?Date.parse(a.ends_on):Infinity;
  if(!Number.isFinite(start)||start>now||end<=start)continue;
  const custody=data.custody.filter(x=>x.vehicle_id===a.vehicle_id);
  const boundaries=[start,end];
  for(const c of custody)for(const value of [Date.parse(c.starts_on),c.ends_on?Date.parse(c.ends_on):Infinity])if(value>start&&value<end)boundaries.push(value);
  const points=[...new Set(boundaries)].sort((a,b)=>a-b);
  for(let i=0;i<points.length-1;i++){
   if(points[i]>now)continue;
   const c=activeFleetAssignment(custody,'vehicle_id',a.vehicle_id,points[i]);
   periods.push({vehicle_id:a.vehicle_id,employee_id:c?.employee_id||null,starts_on:new Date(points[i]).toISOString(),ends_on:Number.isFinite(points[i+1])?new Date(points[i+1]).toISOString():null});
  }
 }
 return periods.sort((a,b)=>Date.parse(b.starts_on)-Date.parse(a.starts_on));
}
function fleetVehicleLabel(v){return v?v.code+' — '+v.description+' · '+(v.plate||tr('اللوحة غير مسجلة','Plate not recorded')):tr('غير مرتبطة بسيارة','Not linked to a vehicle');}
